import 'dart:async';import 'dart:convert';import 'package:flutter/material.dart';import 'package:flutter_map/flutter_map.dart';import 'package:geolocator/geolocator.dart';import 'package:latlong2/latlong.dart';import '../../data/bus_route.dart';import '../../data/bus_station.dart';import '../../data/route_path.dart';import '../../data/route_stations.dart';import '../../utils/static.dart';import '../../widgets/editor/editor_side_panel.dart';import '../../widgets/editor/map_controls.dart';import '../../widgets/editor/map_view_section.dart';import '../../widgets/editor/source_sidebar.dart';import '../../widgets/editor/station_dialog.dart';class RouteEditorPage extends StatefulWidget {  final BusRoute? initialRoute;  const RouteEditorPage({super.key, this.initialRoute});  @override  State<RouteEditorPage> createState() => _RouteEditorPageState();}enum PathAddMode { none, intermediate, end }class _RouteEditorPageState extends State<RouteEditorPage> {  final _idCtrl = TextEditingController(),      _nameCtrl = TextEditingController(),      _descCtrl = TextEditingController(),      _depCtrl = TextEditingController(),      _destCtrl = TextEditingController(),      _wktGoCtrl = TextEditingController(),      _wktBackCtrl = TextEditingController(),      _jsonCtrl = TextEditingController();  List<BusStation> _goStations = [], _backStations = [];  List<LatLng> _goPath = [], _backPath = [];  bool _isEditingGo = true,      _isMapTapMode = false,      _isPathEditing = false,      _isDirty = false,      _isFabMenuExpanded = false,      _isJsonMode = false;  PathAddMode _pathAddMode = PathAddMode.none;  int? _movingStationIndex, _movingPathIndex;  LatLng? _previewPoint;  final MapController _mapController = MapController();  double _brightness = 0.6;  Set<String> _selectedSources = {'Taoyuan'};  List<BusStation> _allSourceStations = [];  List<BusStation> _nearbySourceStations = [];  Timer? _mapMoveTimer;  @override  void initState() {    super.initState();    if (widget.initialRoute != null) {      final r = widget.initialRoute!;      _idCtrl.text = r.id;      _nameCtrl.text = r.name;      _descCtrl.text = r.description;      _depCtrl.text = r.departure;      _destCtrl.text = r.destination;      _wktGoCtrl.text = r.path.go;      _wktBackCtrl.text = r.path.back;      _goStations = List.from(r.stations.go);      _backStations = List.from(r.stations.back);    }    _loadSourceStations(initial: true);    _syncPaths();    WidgetsBinding.instance.addPostFrameCallback((_) => _recenterMap());  }  @override  void dispose() {    _idCtrl.dispose();    _nameCtrl.dispose();    _descCtrl.dispose();    _depCtrl.dispose();    _destCtrl.dispose();    _wktGoCtrl.dispose();    _wktBackCtrl.dispose();    _jsonCtrl.dispose();    _mapMoveTimer?.cancel();    _mapController.dispose();    super.dispose();  }  void _recenterMap() {    if (!mounted) return;    final List<LatLng> allPoints = [      ..._goPath,      ..._backPath,      ..._goStations.map((s) => LatLng(s.lat, s.lon)),      ..._backStations.map((s) => LatLng(s.lat, s.lon)),    ].where((p) => p.latitude != 0 && p.longitude != 0).toList();    if (allPoints.isEmpty) {      _mapController.move(const LatLng(24.9892, 121.3135), 16);    } else {      final bounds = LatLngBounds.fromPoints(allPoints);      _mapController.fitCamera(        CameraFit.bounds(bounds: bounds, padding: const EdgeInsets.all(50)),      );    }    _filterNearbyStations(_mapController.camera.center);  }  void _syncPaths() {    setState(() {      _goPath = Static.wktPrase(_wktGoCtrl.text);      _backPath = Static.wktPrase(_wktBackCtrl.text);    });  }  void _markDirty() => setState(() => _isDirty = true);  String _generateWkt(List<LatLng> pts) {    if (pts.isEmpty) return "";    final sb = StringBuffer("LINESTRING (");    for (int i = 0; i < pts.length; i++) {      sb.write("${pts[i].longitude} ${pts[i].latitude}");      if (i < pts.length - 1) sb.write(", ");    }    sb.write(")");    return sb.toString();  }  void _loadSourceStations({bool initial = false}) {    final List<BusStation> temp = [];    final Set<String> seen = {};    for (var src in _selectedSources) {      final routes = Static.routeData[src];      if (routes == null) continue;      for (var r in routes) {        for (var s in [...r.stations.go, ...r.stations.back]) {          if (seen.add(            "${s.lat.toStringAsFixed(5)}_${s.lon.toStringAsFixed(5)}",          ))            temp.add(s);        }      }    }    _allSourceStations = temp;    if (!initial && mounted)      _filterNearbyStations(_mapController.camera.center);  }  void _filterNearbyStations(LatLng center) {    if (!mounted) return;    setState(() {      _nearbySourceStations = _allSourceStations          .where(            (s) =>                Geolocator.distanceBetween(                  center.latitude,                  center.longitude,                  s.lat,                  s.lon,                ) <=                500,          )          .toList();    });  }  void _toggleJsonMode() {    if (_isJsonMode) {      try {        final Map<String, dynamic> data = jsonDecode(_jsonCtrl.text);        final newRoute = BusRoute.fromJson(data);        setState(() {          _idCtrl.text = newRoute.id;          _nameCtrl.text = newRoute.name;          _descCtrl.text = newRoute.description;          _depCtrl.text = newRoute.departure;          _destCtrl.text = newRoute.destination;          _wktGoCtrl.text = newRoute.path.go;          _wktBackCtrl.text = newRoute.path.back;          _goStations = List.from(newRoute.stations.go);          _backStations = List.from(newRoute.stations.back);          _isJsonMode = false;        });        _syncPaths();      } catch (e) {        showDialog(          context: context,          builder: (ctx) => AlertDialog(            title: const Text("JSON 錯誤"),            content: Text(e.toString()),            actions: [              TextButton(                onPressed: () => Navigator.pop(ctx),                child: const Text("確定"),              ),            ],          ),        );      }    } else {      _jsonCtrl.text = const JsonEncoder.withIndent(        '  ',      ).convert(_prepareRouteData().toJson());      setState(() => _isJsonMode = true);    }  }  BusRoute _prepareRouteData() => BusRoute(    id: _idCtrl.text.trim(),    name: _nameCtrl.text.trim(),    description: _descCtrl.text.trim(),    departure: _depCtrl.text.trim(),    destination: _destCtrl.text.trim(),    path: RoutePath(go: _wktGoCtrl.text, back: _wktBackCtrl.text),    stations: RouteStations(go: _goStations, back: _backStations),  );  Future<void> _handleSave() async {    if (_idCtrl.text.trim().isEmpty || _nameCtrl.text.trim().isEmpty) {      ScaffoldMessenger.of(        context,      ).showSnackBar(const SnackBar(content: Text("ID 與名稱為必填項目")));      return;    }    final route = _prepareRouteData();    try {      await Static.saveCustomRoute(route, oldId: widget.initialRoute?.id);      setState(() => _isDirty = false);      if (mounted) {        ScaffoldMessenger.of(          context,        ).showSnackBar(const SnackBar(content: Text("儲存成功")));        Navigator.pop(context, true);      }    } catch (e) {      if (mounted)        ScaffoldMessenger.of(          context,        ).showSnackBar(SnackBar(content: Text("儲存失敗: $e")));    }  }  double _distanceToSegment(LatLng p, LatLng a, LatLng b) {    double x = p.longitude, y = p.latitude;    double x1 = a.longitude, y1 = a.latitude;    double x2 = b.longitude, y2 = b.latitude;    double dx = x2 - x1, dy = y2 - y1;    if (dx == 0 && dy == 0) return Geolocator.distanceBetween(y, x, y1, x1);    double t = ((x - x1) * dx + (y - y1) * dy) / (dx * dx + dy * dy);    t = t.clamp(0.0, 1.0);    return Geolocator.distanceBetween(y, x, y1 + t * dy, x1 + t * dx);  }  int _getInsertIndex(LatLng point, List<LatLng> path) {    if (path.length < 2) return -1;    double minDistance = double.infinity;    int insertIdx = -1;    for (int i = 0; i < path.length - 1; i++) {      double dist = _distanceToSegment(point, path[i], path[i + 1]);      if (dist < minDistance && dist < 15) {        minDistance = dist;        insertIdx = i + 1;      }    }    return insertIdx;  }  void _onMapStationTap(LatLng p, {BusStation? existing}) async {    final list = _isEditingGo ? _goStations : _backStations;    final result = await showDialog<Map<String, dynamic>>(      context: context,      builder: (ctx) =>          StationDialog(point: p, existing: existing, currentList: list),    );    if (result != null) {      setState(() {        if (result['action'] == 'delete' && existing != null)          list.remove(existing);        else if (result['action'] == 'move')          _movingStationIndex = list.indexOf(existing!);        else if (result['action'] == 'save') {          if (existing != null)            list[list.indexOf(existing)] = result['station'];          else {            final pos = result['order'] as int;            if (pos > 0 && pos <= list.length)              list.insert(pos - 1, result['station']);            else              list.add(result['station']);          }        }        _markDirty();      });    }  }  Future<void> _onPathNodeTap(int index) async {    final result = await showDialog<String>(      context: context,      builder: (ctx) => AlertDialog(        title: Text("節點 #${index + 1}"),        actions: [          TextButton(            onPressed: () => Navigator.pop(ctx, "delete"),            child: const Text("刪除", style: TextStyle(color: Colors.red)),          ),          TextButton(            onPressed: () => Navigator.pop(ctx, "move"),            child: const Text("移動"),          ),          TextButton(            onPressed: () => Navigator.pop(ctx),            child: const Text("關閉"),          ),        ],      ),    );    if (result == "delete") {      setState(() {        final p = List<LatLng>.from(_isEditingGo ? _goPath : _backPath);        p.removeAt(index);        final wkt = _generateWkt(p);        if (_isEditingGo)          _wktGoCtrl.text = wkt;        else          _wktBackCtrl.text = wkt;        _markDirty();      });      _syncPaths();    } else if (result == "move")      setState(() => _movingPathIndex = index);  }  void _onPositionChanged(MapCamera camera) {    setState(() => _previewPoint = camera.center);    if (_movingStationIndex != null) {      setState(() {        final list = _isEditingGo ? _goStations : _backStations;        final s = list[_movingStationIndex!];        list[_movingStationIndex!] = BusStation(          order: s.order,          name: s.name,          nameEn: s.nameEn,          lat: camera.center.latitude,          lon: camera.center.longitude,        );      });    } else if (_movingPathIndex != null) {      setState(() {        final p = List<LatLng>.from(_isEditingGo ? _goPath : _backPath);        p[_movingPathIndex!] = camera.center;        final wkt = _generateWkt(p);        if (_isEditingGo)          _wktGoCtrl.text = wkt;        else          _wktBackCtrl.text = wkt;      });    }    _mapMoveTimer?.cancel();    _mapMoveTimer = Timer(      const Duration(milliseconds: 150),      () => _filterNearbyStations(camera.center),    );  }  void _handleConfirmAddOrMove() {    setState(() {      if (_movingStationIndex != null || _movingPathIndex != null) {        _movingStationIndex = null;        _movingPathIndex = null;      } else if (_isMapTapMode || _pathAddMode == PathAddMode.end) {        final pos = _mapController.camera.center;        if (_isPathEditing && _pathAddMode == PathAddMode.end) {          final pList = List<LatLng>.from(_isEditingGo ? _goPath : _backPath);          pList.add(pos);          final wkt = _generateWkt(pList);          if (_isEditingGo)            _wktGoCtrl.text = wkt;          else            _wktBackCtrl.text = wkt;        } else if (!_isPathEditing && _isMapTapMode) {          _onMapStationTap(pos);          _isMapTapMode = false;        }      }      _markDirty();    });    _syncPaths();  }  @override  Widget build(BuildContext context) {    bool isMoving = _movingStationIndex != null || _movingPathIndex != null;    bool isAdding = _isMapTapMode || _pathAddMode != PathAddMode.none;    bool showCenterControls =        _isMapTapMode || _pathAddMode == PathAddMode.end || isMoving;    final activePath = _isEditingGo ? _goPath : _backPath;    return PopScope(      canPop: !_isDirty,      onPopInvokedWithResult: (didPop, r) async {        if (didPop) return;        final leave = await showDialog<bool>(          context: context,          builder: (ctx) => AlertDialog(            title: const Text("尚未儲存"),            content: const Text("確定要離開嗎？"),            actions: [              TextButton(                onPressed: () => Navigator.pop(ctx, false),                child: const Text("取消"),              ),              TextButton(                onPressed: () => Navigator.pop(ctx, true),                child: const Text("離開", style: TextStyle(color: Colors.red)),              ),            ],          ),        );        if (leave == true) Navigator.pop(context);      },      child: Theme(        data: ThemeData.dark(),        child: Scaffold(          appBar: AppBar(            toolbarHeight: 40,            title: const Text("路線編輯", style: TextStyle(fontSize: 14)),            actions: [              TextButton.icon(                onPressed: _toggleJsonMode,                icon: Icon(_isJsonMode ? Icons.map : Icons.code),                label: Text(_isJsonMode ? "視覺編輯" : "JSON"),              ),              const SizedBox(width: 8),              FilledButton.icon(                onPressed: _handleSave,                icon: const Icon(Icons.save, size: 16),                label: const Text("儲存"),              ),              const SizedBox(width: 8),            ],          ),          body: _isJsonMode              ? _buildJson()              : _buildGui(isMoving, isAdding, showCenterControls, activePath),        ),      ),    );  }  Widget _buildGui(    bool isMoving,    bool isAdding,    bool showCenterControls,    List<LatLng> activePath,  ) => Row(    children: [      EditorSidePanel(        idCtrl: _idCtrl,        nameCtrl: _nameCtrl,        descCtrl: _descCtrl,        depCtrl: _depCtrl,        destCtrl: _destCtrl,        wktCtrl: _isEditingGo ? _wktGoCtrl : _wktBackCtrl,        isEditingGo: _isEditingGo,        autoWkt: false,        isPathEditing: _isPathEditing,        stations: _isEditingGo ? _goStations : _backStations,        pathPoints: activePath,        onDirectionChanged: (v) => setState(() => _isEditingGo = v),        onAutoWktChanged: (v) {},        onWktManualChanged: _syncPaths,        onTogglePathEdit: () => setState(() {          _isPathEditing = !_isPathEditing;          _isMapTapMode = false;          _pathAddMode = PathAddMode.none;        }),        onReorder: (o, n) {          setState(() {            final l = _isEditingGo ? _goStations : _backStations;            if (n > o) n -= 1;            l.insert(n, l.removeAt(o));            _markDirty();          });        },        onStationRemove: (i) => _onMapStationTap(          LatLng(0, 0),          existing: (_isEditingGo ? _goStations : _backStations)[i],        ),        onStationTap: (i, s) =>            _onMapStationTap(LatLng(s.lat, s.lon), existing: s),        onPathPointTap: (idx) => _onPathNodeTap(idx),      ),      const VerticalDivider(width: 1),      Expanded(        child: Stack(          children: [            MapViewSection(              mapController: _mapController,              goPath: _goPath,              backPath: _backPath,              isEditingGo: _isEditingGo,              brightness: _brightness,              nearbySourceStations: _nearbySourceStations,              goStations: _goStations,              backStations: _backStations,              isMapTapMode: showCenterControls,              isPathEditing: _isPathEditing,              movingStationIndex: _movingStationIndex,              movingPathIndex: _movingPathIndex,              previewPoint: showCenterControls ? _previewPoint : null,              onPositionChanged: _onPositionChanged,              onMapTap: (p) {                if (_isPathEditing &&                    _pathAddMode == PathAddMode.intermediate) {                  final pList = List<LatLng>.from(                    _isEditingGo ? _goPath : _backPath,                  );                  int insertIdx = _getInsertIndex(p, pList);                  if (insertIdx != -1) {                    setState(() {                      pList.insert(insertIdx, p);                      final wkt = _generateWkt(pList);                      if (_isEditingGo)                        _wktGoCtrl.text = wkt;                      else                        _wktBackCtrl.text = wkt;                      _markDirty();                    });                    _syncPaths();                  }                }              },              onMarkerTap: (LatLng p, BusStation s) {                if (!isAdding && !isMoving) _onMapStationTap(p, existing: s);              },              onPathPointTap: (int idx) {                if (!isAdding && !isMoving) _onPathNodeTap(idx);              },            ),            Positioned(              bottom: 20,              right: 85,              child: MapControls(                isFabMenuExpanded: _isFabMenuExpanded,                brightness: _brightness,                onToggleFab: () =>                    setState(() => _isFabMenuExpanded = !_isFabMenuExpanded),                onRecenter: _recenterMap,                onBrightnessChanged: (v) => setState(() => _brightness = v),              ),            ),            SourceSidebar(              selectedSources: _selectedSources,              onSourceToggle: (key) {                setState(() {                  if (_selectedSources.contains(key))                    _selectedSources.remove(key);                  else                    _selectedSources.add(key);                });                _loadSourceStations();              },            ),            Positioned(              bottom: 20,              left: 20,              child: Row(                children: [                  if (showCenterControls)                    FilledButton.icon(                      onPressed: _handleConfirmAddOrMove,                      icon: const Icon(Icons.check),                      label: Text(isMoving ? "確認移動" : "確認新增"),                      style: FilledButton.styleFrom(                        backgroundColor: Colors.green,                      ),                    ),                  const SizedBox(width: 8),                  if (!showCenterControls &&                      _pathAddMode == PathAddMode.none) ...[                    if (_isPathEditing) ...[                      FilledButton.icon(                        onPressed: () => setState(                          () => _pathAddMode = PathAddMode.intermediate,                        ),                        icon: const Icon(Icons.add_road),                        label: const Text("中間節點"),                      ),                      const SizedBox(width: 8),                      FilledButton.icon(                        onPressed: () =>                            setState(() => _pathAddMode = PathAddMode.end),                        icon: const Icon(Icons.polyline),                        label: const Text("末端節點"),                      ),                    ] else                      FilledButton.icon(                        onPressed: () => setState(() => _isMapTapMode = true),                        icon: const Icon(Icons.add_location),                        label: const Text("新增站點"),                      ),                  ],                  if (showCenterControls ||                      _pathAddMode != PathAddMode.none) ...[                    const SizedBox(width: 8),                    FilledButton.icon(                      onPressed: () {                        setState(() {                          _isMapTapMode = false;                          _pathAddMode = PathAddMode.none;                          _movingStationIndex = null;                          _movingPathIndex = null;                        });                        _syncPaths();                      },                      icon: const Icon(Icons.close),                      label: const Text("取消"),                      style: FilledButton.styleFrom(                        backgroundColor: Colors.red,                      ),                    ),                  ],                ],              ),            ),          ],        ),      ),    ],  );  Widget _buildJson() => Padding(    padding: const EdgeInsets.all(12),    child: TextField(      controller: _jsonCtrl,      maxLines: null,      expands: true,      style: const TextStyle(fontFamily: 'monospace', fontSize: 11),      decoration: const InputDecoration(        border: OutlineInputBorder(),        hintText: "貼上 JSON...",      ),    ),  );}